        for r_fill in range(max(0, top_r - 1), bottom_r + 1):
            for c_fill in range(W):
                if grid[r_fill][c_fill] == 5:
                    continue

                if r_fill == top_r - 1 and 0 <= c_fill <= right_c - 1:
